// ─── File: LatestOrderDemo.java ───
// "Latest order was cancelled": wrong filter-first vs correct rank-then-filter.
package com.bank.latestorder;

import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class LatestOrderDemo {
    private static final Logger log = Logger.getLogger(LatestOrderDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrderRepository repo = new OrderRepository();
        LatestOrderService service = new LatestOrderService(repo);

        log.info("=== WRONG: filter status='CANCELLED' first, then latest ===");
        service.latestWasCancelledWrong().forEach(id ->
            log.warning(() -> "flagged: " + id + " (includes false positives!)"));

        log.info("=== CORRECT: rank over ALL orders, then test status ===");
        service.latestWasCancelledCorrect().forEach(id ->
            log.info(() -> "flagged: " + id));
    }
}

// ─── Would be in model/Order.java ───
class Order {
    final String orderId, customerId, status, createdAt;
    Order(String id, String cust, String status, String at) {
            this.orderId = id;
            this.customerId = cust
            this.status = status
            this.createdAt = at;
    }
}

// ─── Would be in repository/OrderRepository.java ───
class OrderRepository {
    List<Order> findAll() {
        return List.of(
            new Order("O1", "C1", "CANCELLED", "2026-10-20 10:00:00"),
            new Order("O2", "C1", "COMPLETED", "2026-10-24 10:00:00"), // C1 latest = COMPLETED
            new Order("O3", "C2", "COMPLETED", "2026-10-21 10:00:00"),
            new Order("O4", "C2", "CANCELLED", "2026-10-25 10:00:00"));// C2 latest = CANCELLED
    }
}

// ─── Would be in service/LatestOrderService.java ───
class LatestOrderService {
    private final OrderRepository repo;
    LatestOrderService(OrderRepository repo) { this.repo = repo; }

    // WRONG: filter cancelled FIRST, then latest-of-survivors.
    List<String> latestWasCancelledWrong() {
        // WHERE status='CANCELLED' removes completed orders before ranking
        Map<String, Order> latestCancelled = repo.findAll().stream()
            .filter(o -> "CANCELLED".equals(o.status))              // pre-filter (the bug)
            .collect(Collectors.groupingBy(o -> o.customerId, LinkedHashMap::new,
                Collectors.collectingAndThen(Collectors.toList(), l ->
                    l.stream().max(Comparator.comparing((Order o) -> o.createdAt)
                        .thenComparing(o -> o.orderId)).orElseThrow())));
        // rn=1 among cancelled → any customer with a cancelled order is flagged
        return new ArrayList<>(latestCancelled.keySet());
    }

    // CORRECT: rank over ALL orders, keep rn=1, THEN test status.
    List<String> latestWasCancelledCorrect() {
        Map<String, Order> latestOverall = repo.findAll().stream()
            .collect(Collectors.groupingBy(o -> o.customerId, LinkedHashMap::new,
                Collectors.collectingAndThen(Collectors.toList(), l ->
                    l.stream().max(Comparator.comparing((Order o) -> o.createdAt)
                        .thenComparing(o -> o.orderId)).orElseThrow()))); // rn=1 over full set
        return latestOverall.entrySet().stream()
            .filter(e -> "CANCELLED".equals(e.getValue().status))   // test AFTER identifying
            .map(Map.Entry::getKey).toList();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
